from datetime import datetime
year_start = datetime(datetime.now().year, 1, 1).strftime('%Y-%m-%d 00:00:00')
N = 15  # or from user request
Move = env['account.move']
Ev = env['calendar.event']
client_field = next((
    name for name, field in Ev._fields.items()
    if field.type == 'many2one'
    and field.comodel_name == 'res.partner'
    and name != 'user_id'
), None)
if not client_field:
    result = {'formatted_text': 'calendar.event has no client partner field in this instance.'}
else:
    invs = Move.search([
        ('move_type', 'in', ('out_invoice', 'out_refund')),
        ('state', '=', 'posted'),
    ])
    client_ids = set(invs.mapped('partner_id').mapped('commercial_partner_id').ids)
    counts = {}
    for ev in Ev.search([(client_field, '!=', False), ('start', '>=', year_start)]):
        cid = ev[client_field].commercial_partner_id.id
        if cid in client_ids:
            counts[cid] = counts.get(cid, 0) + 1
    ranked = sorted(counts.items(), key=lambda x: (-x[1], x[0]))[:N]
    Partner = env['res.partner']
    result = [
        {'id': pid, 'name': Partner.browse(pid).display_name, 'events_ytd': n}
        for pid, n in ranked
    ]

# Hierarchy: State > Country > City
loc = env['res.country.state'].search([('name', 'ilike', t)], limit=1)
if loc: res = env['res.partner'].search([('state_id', '=', loc.id)])
else:
    loc = env['res.country'].search([('name', 'ilike', t)], limit=1)
    if loc: res = env['res.partner'].search([('country_id', '=', loc.id)])
    else: res = env['res.partner'].search(['|', ('city', 'ilike', t), ('zip', '=like', f"{t}%")])
